{
  "id": 27,
  "knowledge": "Information Leakage Score Interpretation",
  "description": "Provides context for the information leakage score, indicating potential trading on non-public information.",
  "definition": "A score from 0-100. Low scores (<20) suggest little evidence of informed trading. Moderate scores (20-50) warrant attention. High scores (>50) strongly suggest trading based on non-public information and require investigation."
}

{
  "id": 4,
  "knowledge": "Pattern Anomaly Score (PAS)",
  "description": "Measures the deviation of a trader's pattern similarity from their peer correlation, potentially indicating unique illicit behavior.",
  "definition": "PAS = |\\text{Pattern Similarity Score} - \\text{Peer Correlation Score}|"
}

{
  "id": 3,
  "knowledge": "Suspicious Activity Index (SAI)",
  "description": "A composite index attempting to quantify overall suspicious trading behavior based on risk indicators.",
  "definition": "SAI is a weighted sum of normalized risk indicators, including probabilities for spoofing, front-running, wash trading, and confirmed layering."
}

{
  "id": 31,
  "knowledge": "Combined Manipulation Indicator (CMI)",
  "description": "A combined score reflecting both general suspicious activity and specific pattern anomalies.",
  "definition": "CMI = ('Suspicious Activity Index' + 'Pattern Anomaly Score') / 2"
}

{
  "id": 36,
  "knowledge": "Aggressive Trading Intensity (ATI)",
  "description": "Measures intensity by combining high turnover, leverage, and order modification frequency.",
  "definition": "ATI = 'Daily Turnover Rate' \\times 'Trader Leverage Exposure' \\times 'Order Modification Intensity'."
}

{
  "id": 64,
  "knowledge": "Volatile Event Speculator",
  "description": "Flags aggressive event speculators whose trading coincides with high sentiment divergence, indicating potential reaction to conflicting information.",
  "definition": "A trader identified as an 'Aggressive Event Speculator' AND associated with a high 'Sentiment Divergence Factor' (e.g., > 1.0)."
}

{
  "id": 0,
  "knowledge": "Daily Turnover Rate (DTR)",
  "description": "Calculates the ratio of a trader's daily trading volume to their account balance, indicating capital velocity.",
  "definition": "DTR = \\frac{\\text{Daily Trading Volume}}{\\text{Account Balance}}"
}

{
  "id": 1,
  "knowledge": "Order Modification Intensity (OMI)",
  "description": "Measures how frequently a trader modifies orders relative to their cancellation rate.",
  "definition": "OMI = \\frac{\\text{Order Modification Frequency}}{1 - \\text{Order Cancellation Percentage}} \\text{ (undefined if cancellation percentage is 1)}"
}

{
  "id": 2,
  "knowledge": "Trader Leverage Exposure (TLE)",
  "description": "Extracts the leverage ratio from the trader's performance data.",
  "definition": "TLE = A trader's leverage ratio, typically found within their performance metrics."
}

{
  "id": 7,
  "knowledge": "Sentiment Divergence Factor (SDF)",
  "description": "Measures the difference between news and social media sentiment scores.",
  "definition": "SDF = |\\text{News Sentiment Score} - \\text{Social Sentiment Score}|"
}

{
  "id": 38,
  "knowledge": "Boosted Insider Leakage Score (BILS)",
  "description": "Increases the Information Leakage Score if a Potential Insider Trading Flag is also present.",
  "definition": "BILS = The raw 'Information Leakage Score' \\times (1.5 \\text{ if 'Potential Insider Trading Flag' is True else } 1.0)"
}

